# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CEZİM (SÜKÛN) VE ŞEDDE İŞARETİNİN TELAFFUZ ÖZELLİKLERİ (KK.5.2.1)</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Cezim / Sükûn (ـْـ) Kuralları</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Harfin üzerinde küçük daire şeklinde yazılır.</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Üzerine geldiği harfin harekesiz olduğunu gösterir.</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Cezimli harf kendinden önceki harekeli harfe</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11.5" fill="#1e3a8a">tutunarak tek hecede okunur (hareke verilmez).</text>\n  <text x="180" y="196" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">مِنْ (min) · عَنْ (an) · أَلَمْ (elem) · يَكْتُبُ (yektübü)</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" fill="#334155">Kelimenin ilk harfinde cezim bulunmaz.</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Şedde (ـّـ) Kuralları</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#831843">• Harfin üzerinde «w» (dişli) sembolüyle gösterilir.</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#831843">• Aynı harfin yan yana iki kez (1.si cezimli,</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11.5" fill="#831843">2.si harekeli) okunmasını sağlar.</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11.5" fill="#831843">• Harf üzerinde kısa bir süre beklenip bastırılır.</text>\n  <text x="520" y="196" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">رَبَّ (rabbe = رَبْ + بَ) · إِنَّ (inne) · جَنَّةٌ (cennetün)</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" fill="#334155">İnna ve enne gibi kelimelerde gunneli tutulur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TENVİN, CEZİM VE ŞEDDE KARŞILAŞTIRMASI TABLOSU</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Tenvin (ـً / ـٍ / ـٌ)</text>\n  <text x="125" y="102" text-anchor="middle" font-size="11.5" fill="#78350f">• Kelimenin son harfinde bulunur.</text>\n  <text x="125" y="128" text-anchor="middle" font-size="11.5" fill="#78350f">• İki üstün (-en/-an), iki esre</text>\n  <text x="125" y="148" text-anchor="middle" font-size="11.5" fill="#78350f">(-in/-ın), iki ötre (-ün/-un) verir.</text>\n  <text x="125" y="176" text-anchor="middle" font-size="11.5" fill="#78350f">• Okunuşta cezimli nun (نْ) sesi</text>\n  <text x="125" y="196" text-anchor="middle" font-size="11.5" fill="#78350f">duyulur fakat nun yazılmaz.</text>\n  <text x="125" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">رَحْمَةٌ (rahmetün) · عِلْمًا (ilmen)</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Cezim / Sükûn (ـْـ)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11.5" fill="#14532d">• Kelime ortasında ve sonunda</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11.5" fill="#14532d">yer alır (başta bulunmaz).</text>\n  <text x="350" y="148" text-anchor="middle" font-size="11.5" fill="#14532d">• Harfe ünlü sesi vermez; önceki</text>\n  <text x="350" y="168" text-anchor="middle" font-size="11.5" fill="#14532d">harfi cezimli harfe bağlar.</text>\n  <text x="350" y="194" text-anchor="middle" font-size="11.5" fill="#14532d">• Kapalı hece oluşturur.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">اَلْحَمْدُ (el-hamdü) · نَعْبُدُ (na\'büdü)</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Şedde (ـّـ)</text>\n  <text x="575" y="102" text-anchor="middle" font-size="11.5" fill="#581c87">• Cezim + Hareke birleşimidir.</text>\n  <text x="575" y="128" text-anchor="middle" font-size="11.5" fill="#581c87">• Harf önce önceki heceye</text>\n  <text x="575" y="148" text-anchor="middle" font-size="11.5" fill="#581c87">bağlanır, sonra kendi harekesiyle</text>\n  <text x="575" y="168" text-anchor="middle" font-size="11.5" fill="#581c87">ikinci kez seslendirilir.</text>\n  <text x="575" y="194" text-anchor="middle" font-size="11.5" fill="#581c87">• Tenvinle de birleşebilir (ـٌّ).</text>\n  <text x="575" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">إِيَّاكَ (iyyâke) · نَبِيٌّ (nebiyyün)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TAHİYYAT DUASI VE SURELERDEN UYGULAMA ÖRNEKLERİ</text>\n  <rect x="20" y="48" width="660" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Bir Kelimede Birden Fazla Okuma Kuralını Birlikte Uygulama</text>\n  <text x="350" y="104" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#164e63">1. اَلتَّحِيَّاتُ (et-tehiyyâtü) → تّ ve يّ şeddeli · ا uzatma (med) harfi</text>\n  <text x="350" y="132" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#164e63">2. اَلطَّيِّبَاتُ (et-tayyibâtü) → طّ ve يّ şeddeli · بَا med harfiyle uzatma</text>\n  <text x="350" y="160" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#164e63">3. وَرَحْمَةُ اللّٰهِ (ve rahmetullâhi) → حْ cezimli (rah) · للّٰ şeddeli ve çekerli</text>\n  <text x="350" y="188" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#164e63">4. أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ → شْ ve نْ cezimli · لَّا ve للّٰ شeddeli</text>\n  <text x="350" y="218" text-anchor="middle" font-size="11.5" fill="#155e75">Kur\'an okurken cezimli harfleri sektirmeden, şeddeli harfleri ise tek harfe düşürmeden okuruz.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
